def is_s_equivalent(S_1, S_2, all_jobs):
    # Condition 1: All jobs in S_1 finish no later than in S_2
    for job in all_jobs:
        if S_1.get_start_time(job) > S_2.get_start_time(job):
            return False # Condition 1 violated

    # Condition 2: Same job ordering
    for job_ij in all_jobs:
        for job_xy in all_jobs:
            if job_ij == job_xy:
                continue
            # Check if order is swapped: job_xy before job_ij in S_1, but job_ij before job_xy in S_2
            if (S_1.get_start_time(job_xy) < S_1.get_start_time(job_ij) and
                    S_2.get_start_time(job_xy) > S_2.get_start_time(job_ij)):
                return False # Condition 2 violated
    return True

class Interval:
    def __init__(self, start, end):
        self.start = start
        self.end = end
    def is_empty(self): return self.start > self.end
    def intersects(self, other): return not (self.end < other.start or other.end < self.start)
    def intersect(self, other):
        new_start = max(self.start, other.start)
        new_end = min(self.end, other.end)
        return Interval(new_start, new_end)

