def is_scheduled_directly_before_fifo(job_xy, job_ij, all_jobs):
    # Condition 1: job_xy is released before or effectively before job_ij
    release_order_ok = False
    if job_xy.release_time < job_ij.release_time:
        release_order_ok = True
    elif job_xy.release_time == job_ij.release_time and job_xy.task_index < job_ij.task_index:
        release_order_ok = True

    if not release_order_ok:
        return False

    # Condition 2: No other job J_p_q is released between job_xy and job_ij
    for job_pq in all_jobs:
        if job_pq == job_xy or job_pq == job_ij:
            continue

        # Check if job_pq is released after or effectively after job_xy
        # AND before or effectively before job_ij
        is_after_xy = False
        if job_pq.release_time > job_xy.release_time:
            is_after_xy = True
        elif job_pq.release_time == job_xy.release_time and job_pq.task_index > job_xy.task_index:
            is_after_xy = True

        is_before_ij = False
        if job_pq.release_time < job_ij.release_time:
            is_before_ij = True
        elif job_pq.release_time == job_ij.release_time and job_pq.task_index < job_ij.task_index:
            is_before_ij = True

        if is_after_xy and is_before_ij:
            return False # An intervening job exists

    return True

def create_initial_release_times(S_ref, all_jobs):
    initial_release_times = {}
    for job in all_jobs:
        initial_release_times[job] = S_ref.get_start_time(job)
    return initial_release_times

