def check_single_offset_feasibility(task_set, S_ref, pois_for_all_jobs):
    # pois_for_all_jobs: A map of job -> POI, obtained from Algorithm 1

    for task_i in task_set:
        # Compute intersection of all POIs for task_i
        current_task_omega_total = None
        for j in range(1, task_i.m_i + 1):
            job_ij = task_i.get_job(j)
            poi_ij = pois_for_all_jobs[job_ij] # Assume this is available

            if current_task_omega_total is None:
                current_task_omega_total = poi_ij
            else:
                current_task_omega_total = current_task_omega_total.intersect(poi_ij)

            if current_task_omega_total.is_empty():
                return False # This task cannot use a single offset

    return True # All tasks can use a single offset
